module Top;
    class Table;
        int id = 1;
        function int next();
            return ++id;
        endfunction
    endclass
    Table t;
    bit [3:0] nibble;
    int s;
    initial begin
        t = new;
        $display("next %0d", t.next());
        nibble = 4'hf;
        s = nibble++;
        $display("wrap %0d %0d", s, nibble);
    end
endmodule
